#!/usr/bin/env bash
set -euo pipefail

# Vendor the CRDs of an External Secrets release into crds/, as compact JSON plus
# an index (crds/main.libsonnet) and the version they came from (crds/VERSION).
#   ./generate-crds.sh v0.18.2
# Needs helm and yq. The tags in images.libsonnet must match (tests check it).
version="${1:?usage: generate-crds.sh <version, e.g. v0.18.2>}"
cd "$(dirname "${BASH_SOURCE[0]}")"

rm -rf crds && mkdir crds
# Collapse the generated files in GitHub diffs and language stats.
printf '# Generated by generate-crds.sh.\n* linguist-generated=true\n' > crds/.gitattributes
helm template external-secrets external-secrets \
  --repo https://charts.external-secrets.io --version "${version#v}" \
  --set installCRDs=true --set crds.createClusterExternalSecret=true \
  --set crds.createClusterSecretStore=true --set crds.createPushSecret=true \
  | yq -o=json -I=0 -s '"crds/" + .metadata.name + ".json"' 'select(.kind == "CustomResourceDefinition")'

{
  echo "// Generated by generate-crds.sh. Do not edit."
  echo "{"
  for f in crds/*.json; do
    n="$(basename "$f" .json)"
    echo "  '$n': import '$n.json',"
  done
  echo "}"
} > crds/main.libsonnet
printf '%s' "$version" > crds/VERSION
